shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-deep: #eae4d7;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c8c0af;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.13);
    --navy-bg: #0f1d2b;
    --navy-card: #16283a;
    --navy-line: #283f56;
    --crimson: #8f2d24;
    --font-display: 'Playfair Display', 'Noto Serif SC', Georgia, serif;
    --font-serif-cn: 'Noto Serif SC', 'Lora', Georgia, serif;
    --font-serif-en: 'Lora', 'Noto Serif SC', Georgia, serif;
    --font-sans: 'Inter', 'Noto Sans SC', -apple-system, BlinkMacSystemFont, sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    font-size: 16px;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    scroll-behavior: smooth;
  }

  .wsj-shadow-body {
    background-color: var(--paper);
    color: var(--body);
    overflow-x: hidden;
    min-height: 100vh;
    position: relative;
  }

  /* Strict Bilingual Display Control */
  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  /* Inline Highlighting */
  mark.ed-hl {
    background: linear-gradient(180deg, transparent 55%, rgba(184, 93, 25, 0.22) 55%);
    color: inherit;
    padding: 0 2px;
    font-weight: 600;
  }

  /* Reading Progress Bar */
  .progress-rail {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 3px;
    background: rgba(20, 20, 19, 0.08);
    z-index: 1000;
  }
  .progress-fill {
    height: 100%;
    width: 0%;
    background: var(--accent);
    transition: width 0.1s ease-out;
  }

  /* Sticky Top Masthead */
  .wsj-masthead {
    position: sticky;
    top: 0;
    z-index: 900;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--line);
    padding: 0.7rem 1.5rem;
  }
  .masthead-inner {
    max-width: 1200px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }
  .brand-cluster {
    display: flex;
    align-items: baseline;
    gap: 0.75rem;
    flex-wrap: wrap;
  }
  .wsj-wordmark {
    font-family: var(--font-display);
    font-weight: 800;
    font-size: 1.05rem;
    letter-spacing: 0.06em;
    color: var(--ink);
    text-transform: uppercase;
  }
  .wsj-divider {
    color: var(--line-strong);
    font-weight: 300;
  }
  .wsj-section-tag {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--accent);
    font-weight: 600;
  }
  .lang-switch {
    display: inline-flex;
    align-items: center;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-radius: 999px;
    padding: 2px;
  }
  .lang-btn {
    appearance: none;
    border: none;
    background: transparent;
    font-family: var(--font-mono);
    font-size: 0.74rem;
    font-weight: 600;
    color: var(--muted);
    padding: 0.28rem 0.72rem;
    border-radius: 999px;
    cursor: pointer;
    transition: all 0.2s ease;
  }
  .lang-btn.active {
    background: var(--ink);
    color: var(--paper);
  }

  /* Hero Header */
  .article-hero {
    max-width: 1200px;
    margin: 0 auto;
    padding: 3.5rem 1.5rem 2.5rem;
    border-bottom: 2px solid var(--ink);
  }
  .hero-kicker-row {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    margin-bottom: 1.25rem;
    flex-wrap: wrap;
  }
  .kicker-pill {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    background: var(--ink);
    color: var(--paper);
    padding: 0.24rem 0.6rem;
    font-weight: 600;
  }
  .kicker-meta {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    color: var(--muted);
    letter-spacing: 0.04em;
  }
  .hero-title {
    font-family: var(--font-display);
    color: var(--ink);
    font-weight: 800;
    font-size: clamp(2.1rem, 4.4vw, 3.6rem);
    line-height: 1.18;
    letter-spacing: -0.015em;
    margin-bottom: 1.35rem;
    max-width: 24ch;
  }
  :host([lang="en"]) .hero-title {
    max-width: 22ch;
    line-height: 1.08;
  }
  .hero-standfirst {
    font-family: var(--font-serif-cn);
    font-size: clamp(1.08rem, 1.6vw, 1.28rem);
    line-height: 1.75;
    color: var(--muted);
    max-width: 760px;
    margin-bottom: 1.85rem;
    padding-left: 1rem;
    border-left: 3px solid var(--accent);
  }
  :host([lang="en"]) .hero-standfirst {
    font-family: var(--font-serif-en);
    line-height: 1.6;
  }
  .hero-byline-bar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    padding-top: 1.15rem;
    border-top: 1px solid var(--line);
    font-family: var(--font-sans);
    font-size: 0.82rem;
    color: var(--muted);
  }
  .byline-authors strong {
    color: var(--ink);
    font-weight: 700;
    letter-spacing: 0.03em;
  }
  .byline-dateline {
    font-family: var(--font-mono);
    font-size: 0.76rem;
  }

  /* Key Figures Strip (Analytical Dispatch Ledger) */
  .dispatch-ledger {
    max-width: 1200px;
    margin: 0 auto;
    padding: 1.75rem 1.5rem;
    border-bottom: 1px solid var(--line);
    background: linear-gradient(180deg, rgba(243, 239, 230, 0.55) 0%, rgba(250, 248, 244, 0) 100%);
  }
  .ledger-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1.25rem;
  }
  .ledger-cell {
    border-left: 2px solid var(--line-strong);
    padding-left: 1rem;
  }
  .ledger-cell.highlight-cell {
    border-left-color: var(--accent);
  }
  .ledger-num {
    font-family: var(--font-mono);
    font-size: 1.65rem;
    font-weight: 700;
    color: var(--ink);
    line-height: 1.15;
    margin-bottom: 0.3rem;
  }
  .ledger-cell.highlight-cell .ledger-num {
    color: var(--accent);
  }
  .ledger-label {
    font-family: var(--font-sans);
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--ink);
    margin-bottom: 0.2rem;
  }
  .ledger-sub {
    font-family: var(--font-sans);
    font-size: 0.74rem;
    color: var(--muted);
    line-height: 1.45;
  }

  /* Main Editorial Container & Asymmetric Grid */
  .editorial-stage {
    max-width: 1200px;
    margin: 0 auto;
    padding: 2.75rem 1.5rem 4rem;
  }
  .editorial-chapter {
    display: grid;
    grid-template-columns: minmax(0, 700px) minmax(280px, 380px);
    justify-content: space-between;
    gap: 3rem;
    margin-bottom: 3.25rem;
    align-items: start;
  }
  .editorial-chapter.single-flow {
    grid-template-columns: minmax(0, 740px);
    justify-content: center;
  }

  /* Chapter Dividers */
  .chapter-banner {
    display: flex;
    align-items: center;
    gap: 0.85rem;
    margin-bottom: 1.6rem;
    padding-bottom: 0.65rem;
    border-bottom: 1px solid var(--ink);
  }
  .chapter-index {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    font-weight: 700;
    color: var(--accent);
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }
  .chapter-heading {
    font-family: var(--font-display);
    font-size: 1.25rem;
    font-weight: 700;
    color: var(--ink);
  }

  /* Prose Typography (Strict CJK Compliance: No text-wrap:pretty, No ::first-letter) */
  .prose-column {
    width: 100%;
  }
  .prose-p {
    font-family: var(--font-serif-cn);
    font-size: 1.125rem;
    line-height: 1.92;
    color: var(--body);
    margin-bottom: 1.5rem;
    letter-spacing: 0.01em;
  }
  :host([lang="en"]) .prose-p {
    font-family: var(--font-serif-en);
    font-size: 1.1rem;
    line-height: 1.78;
    letter-spacing: 0;
  }
  /* Lead Paragraph Scale + Border Treatment instead of ::first-letter */
  .prose-p.lead-para {
    font-size: 1.24rem;
    line-height: 1.85;
    color: var(--ink);
    font-weight: 600;
    padding: 1.15rem 1.35rem;
    background: var(--paper-card);
    border-left: 4px solid var(--ink);
    margin-bottom: 1.85rem;
  }
  :host([lang="en"]) .prose-p.lead-para {
    font-size: 1.2rem;
    line-height: 1.72;
  }

  /* Sidebar Dossiers & Cards */
  .sidebar-rail {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
    position: sticky;
    top: 4.5rem;
  }
  .dossier-box {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-top: 3px solid var(--ink);
    padding: 1.35rem;
  }
  .dossier-box.accent-top {
    border-top-color: var(--accent);
  }
  .dossier-eyebrow {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    color: var(--accent);
    margin-bottom: 0.5rem;
  }
  .dossier-title {
    font-family: var(--font-display);
    font-size: 1.08rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.85rem;
    line-height: 1.35;
  }
  .dossier-list {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 0.8rem;
  }
  .dossier-item {
    padding-top: 0.75rem;
    border-top: 1px dashed var(--line-strong);
    font-family: var(--font-sans);
    font-size: 0.83rem;
    line-height: 1.55;
    color: var(--body);
  }
  .dossier-item:first-child {
    padding-top: 0;
    border-top: none;
  }
  .dossier-item strong {
    display: block;
    color: var(--ink);
    font-weight: 700;
    margin-bottom: 0.15rem;
  }

  /* Contrasting Claims Table inside Chapter 1 */
  .claims-matrix {
    margin: 2rem 0;
    border: 1px solid var(--line-strong);
    background: var(--paper-card);
  }
  .claims-header {
    background: var(--ink);
    color: var(--paper);
    padding: 0.7rem 1.15rem;
    font-family: var(--font-mono);
    font-size: 0.74rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }
  .claims-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }
  .claim-col {
    padding: 1.25rem;
  }
  .claim-col:first-child {
    border-right: 1px solid var(--line-strong);
  }
  .claim-badge {
    display: inline-block;
    font-family: var(--font-mono);
    font-size: 0.68rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    padding: 0.18rem 0.5rem;
    margin-bottom: 0.6rem;
    background: var(--paper-deep);
    color: var(--ink);
  }
  .claim-badge.critic {
    background: var(--accent-soft);
    color: var(--accent);
  }
  .claim-heading {
    font-family: var(--font-sans);
    font-size: 0.92rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.45rem;
  }
  .claim-desc {
    font-family: var(--font-sans);
    font-size: 0.82rem;
    line-height: 1.55;
    color: var(--muted);
  }

  /* Dark Navy Security Lockdown Dossier (Chapter 2 Visual Break) */
  .lockdown-canvas {
    background: var(--navy-bg);
    color: #f2efe9;
    padding: 2.25rem;
    margin: 2.25rem 0 2.75rem;
    border-top: 4px solid var(--accent);
    box-shadow: 0 14px 34px rgba(15, 29, 43, 0.12);
  }
  .lockdown-top {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: flex-end;
    gap: 1rem;
    padding-bottom: 1.15rem;
    border-bottom: 1px solid var(--navy-line);
    margin-bottom: 1.5rem;
  }
  .lockdown-kicker {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: #e89554;
    margin-bottom: 0.35rem;
  }
  .lockdown-title {
    font-family: var(--font-display);
    font-size: 1.45rem;
    font-weight: 700;
    color: #ffffff;
  }
  .lockdown-note {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    color: #9cb0c4;
  }
  .svg-wrapper {
    width: 100%;
    background: var(--navy-card);
    border: 1px solid var(--navy-line);
    padding: 0.75rem;
  }
  .lockdown-caption {
    margin-top: 0.9rem;
    font-family: var(--font-sans);
    font-size: 0.78rem;
    color: #b0c0d0;
    line-height: 1.5;
  }

  /* Split Sentence Dramatic Callout (p7.s2) */
  .dramatic-shout-box {
    margin: 1.5rem 0 1.85rem;
    padding: 1.35rem 1.6rem;
    background: var(--paper-card);
    border-left: 4px solid var(--crimson);
    font-family: var(--font-display);
    font-size: 1.35rem;
    font-weight: 700;
    color: var(--ink);
    line-height: 1.45;
  }

  /* Human Feature / Name Discrepancy Forensic Diagram (Chapter 3) */
  .forensic-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.5rem;
    margin: 1.75rem 0;
  }
  .forensic-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 1px solid var(--line-strong);
    padding-bottom: 0.75rem;
    margin-bottom: 1rem;
  }
  .forensic-tag {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
  }
  .forensic-loc {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    color: var(--muted);
  }

  /* Climactic Direct Quote (p12.s4) */
  .verdict-quote {
    margin: 1.75rem 0 2rem;
    padding: 1.65rem 1.85rem;
    background: var(--ink);
    color: var(--paper);
    border-left: 5px solid var(--accent);
    font-family: var(--font-display);
    font-size: clamp(1.3rem, 2.2vw, 1.65rem);
    font-weight: 700;
    line-height: 1.45;
  }

  /* Derived Pull Quote Styling (when used in separate section) */
  .pull-quote {
    background: var(--paper-card);
    border-top: 2px solid var(--ink);
    border-bottom: 1px solid var(--line-strong);
    padding: 1.35rem 1.15rem;
  }
  .pull-quote .quote-text {
    font-family: var(--font-serif-cn);
    font-size: 0.95rem;
    font-style: italic;
    line-height: 1.65;
    color: var(--ink);
    margin-bottom: 0.65rem;
  }
  .pull-quote .quote-attrib {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }

  /* Footer */
  .wsj-footer {
    border-top: 2px solid var(--ink);
    background: var(--paper-card);
    padding: 2.5rem 1.5rem;
    margin-top: 2rem;
  }
  .footer-inner {
    max-width: 1200px;
    margin: 0 auto;
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: center;
    gap: 1rem;
    font-family: var(--font-mono);
    font-size: 0.75rem;
    color: var(--muted);
  }

  /* Responsive Mobile Reflow (390px and below) */
  @media (max-width: 960px) {
    .ledger-grid {
      grid-template-columns: repeat(2, 1fr);
    }
    .editorial-chapter {
      grid-template-columns: 1fr;
      gap: 2rem;
    }
    .sidebar-rail {
      position: static;
    }
  }

  @media (max-width: 600px) {
    .wsj-masthead {
      padding: 0.6rem 1rem;
    }
    .article-hero {
      padding: 2.25rem 1rem 1.75rem;
    }
    .dispatch-ledger {
      padding: 1.35rem 1rem;
    }
    .ledger-grid {
      grid-template-columns: 1fr;
      gap: 1rem;
    }
    .editorial-stage {
      padding: 2rem 1rem 3rem;
    }
    .claims-grid {
      grid-template-columns: 1fr;
    }
    .claim-col:first-child {
      border-right: none;
      border-bottom: 1px solid var(--line-strong);
    }
    .lockdown-canvas {
      padding: 1.35rem 1rem;
    }
    .prose-p.lead-para {
      padding: 1rem;
      font-size: 1.12rem;
    }
    .verdict-quote {
      padding: 1.25rem;
    }
  }
